import React, { useState, useEffect } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import API_BASE_URL from "../config";
import "../styles/Checkout.css";

const Checkout = () => {
  const [shippingInfo, setShippingInfo] = useState({
    address: "",
    city: "",
    state: "",
    zip: "",
  });
  const [orderSummary, setOrderSummary] = useState(null);
  const userId = sessionStorage.getItem("userId");
  const buyerName = sessionStorage.getItem("username");

  useEffect(() => {
    const summary = JSON.parse(sessionStorage.getItem("orderSummary"));
    setOrderSummary(summary);
  }, []);

  const handleChange = (e) => {
    setShippingInfo({ ...shippingInfo, [e.target.name]: e.target.value });
  };

  const placeOrder = async () => {
    const res = await fetch(`${API_BASE_URL}/api/orders`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        user_id: userId,
        items: orderSummary.items,
        total: orderSummary.total,
        shipping_info: shippingInfo,
        buyer_name: buyerName,
      }),
    });

    const data = await res.json();
    if (res.ok) {
      alert("✅ Order placed successfully!");
      sessionStorage.removeItem("cartItems");
      sessionStorage.removeItem("orderSummary");
      window.location.href = "/";
    } else {
      alert(`❌ Failed to place order: ${data.message}`);
    }
  };

  if (!orderSummary) return <p>Loading...</p>;

  return (
    <div className="checkout-wrapper">
      <Navbar />
      <div className="checkout-main">
        <div className="shipping-form">
          <h2>Shipping Info</h2>
          <input name="address" placeholder="Address" onChange={handleChange} />
          <input name="city" placeholder="City" onChange={handleChange} />
          <input name="state" placeholder="State" onChange={handleChange} />
          <input name="zip" placeholder="Zip Code" onChange={handleChange} />
        </div>

        <div className="order-summary">
          <h3>Order Details</h3>
          {orderSummary.items.map((item, index) => (
            <div key={index}>
              <strong>{item.title}</strong>: ${item.price}
            </div>
          ))}
          <p>Subtotal: ${orderSummary.subtotal}</p>
          <p>Tax: ${orderSummary.tax}</p>
          <p>Shipping: ${orderSummary.shipping}</p>
          <p><strong>Total: ${orderSummary.total}</strong></p>
          <button onClick={placeOrder}>Place Order</button>
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default Checkout;
